import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine());
        int[][] probabilities = new int[n][n];

        long inv100 = modPow(100, MOD - 2); // Modular inverse of 100

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(st.nextToken());
                probabilities[i][j] = (int)((long)val * inv100 % MOD);
            }
        }

        List<int[]>[] sizeGroups = new ArrayList[n + 1];
        List<int[]>[] subsetList = new ArrayList[n + 1];

        for (int size = 0; size <= n; size++) {
            sizeGroups[size] = new ArrayList<>();
            subsetList[size] = new ArrayList<>();
        }

        for (int s = 0; s < (1 << n); s++) {
            int c = Integer.bitCount(s);
            sizeGroups[c].add(s);
            subsetList[c].add(s);
        }

        Map<Long, Long>[] dp = new HashMap[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new HashMap<>();
        }
        dp[0].put(1L, 1L);

        for (int i = 1; i <= n; i++) {
            for (int s = 0; s < (1 << n); s++) {
                long productProb = 1L;
                for (int j = 0; j < n; j++) {
                    if (((s >> j) & 1) == 1) {
                        productProb = (productProb * probabilities[i - 1][j]) % MOD;
                    } else {
                        productProb = (productProb * (MOD + 1 - probabilities[i - 1][j])) % MOD;
                    }
                }
                for (Map.Entry<Long, Long> entry : dp[i - 1].entrySet()) {
                    long f = entry.getKey();
                    long count = entry.getValue();
                    long mask = 0L;
                    for (int t : subsetList[i]) {
                        for (int j = 0; j < n; j++) {
                            if (((t >> j) & 1) == 1 && ((s >> j) & 1) == 1) {
                                int prevSize = sizeGroups[i - 1].get(0) == null ? 0 : sizeGroups[i - 1].size();
                                for (int idx = 0; idx < sizeGroups[i - 1].size(); idx++) {
                                    int tVal = sizeGroups[i - 1].get(idx);
                                    if (((tVal ^ (1 << j)) & tVal) == 0) {
                                        long bit = 1L << sizeGroups[i][t];
                                        if ((f & bit) != 0) {
                                            mask |= bit;
                                            break;
                                        }
                                    }
                                }
                                break;
                            }
                        }
                    }
                    long newVal = (dp[i].getOrDefault(mask, 0L) + count * productProb) % MOD;
                    dp[i].put(mask, newVal);
                }
            }
        }

        System.out.println(dp[n].getOrDefault(1L, 0L));
    }
}
